#include <bits/stdc++.h>
using namespace std;

namespace IO {
	template<typename T>
	inline int Read(T &n) {
		T k=0, f=1; char c=getchar();
		while (c<'0' || c>'9') { if (c=='-') f=-1; c=getchar(); }
		while (c>='0' && c<='9') { k=(k<<3)+(k<<1)+(c-'0'); c=getchar(); }
		n = k*f; return 0;
	}
	template<typename T>
	inline void Write(T x) {
		if (x < 0) { putchar('-'); x=-x; }
		if (x > 9) Write(x/10);
		putchar(x%10+'0');
	}
	template<typename T, typename ...Y>
	inline int Read(T &x, Y&... y) { return Read(x) | Read(y...); }
}

#define LL long long
#define FOR(i, a, b) for(LL i=(a); i<=(b); i++)
#define ROF(i, a, b) for(LL i=(a); i>=(b); i--)

const LL MOD_A = 998244353, MOD_B = 1000000007;
LL total_answer, total_n, count_one, sum_per_level[7];
vector<LL> level_vals[7];

inline void build_levels(LL level, LL prefix) {
	if (level == 7) return;
	level_vals[level].push_back((count_one - prefix + MOD_A) % MOD_A);
	sum_per_level[level] += (count_one - prefix + MOD_A) % MOD_A;
	count_one++;
	FOR(d, 0, 9) build_levels(level + 1, prefix * 10 + d);
}

inline bool check_range(LL x) {
	const LL limit = 1e6;
	return x * limit + 999999 <= total_n && x * limit * 10 > total_n;
}

LL total_count, power[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

inline void traverse(LL level, LL num) {
	if (num > total_n) return;
	if (check_range(num)) {
		FOR(i, 0, 6) {
			LL current_val = ((total_count + 1 - (num * power[i])) % MOD_A + MOD_A) % MOD_A;
			LL pos = lower_bound(level_vals[i].begin(), level_vals[i].end(), MOD_A - current_val) - level_vals[i].begin();
			total_answer += sum_per_level[i] + current_val * level_vals[i].size() - MOD_A * (level_vals[i].size() - pos);
			total_answer %= MOD_B;
		}
		total_count += count_one;
	} else {
		total_count++;
		total_answer += ((total_count - num) % MOD_A + MOD_A) % MOD_A;
		FOR(i, 0, 9) traverse(level + 1, num * 10 + i);
	}
}

int main() {
	IO::Read(total_n);
	build_levels(0, 0);
	for (int i=0; i<=6; ++i) sort(level_vals[i].begin(), level_vals[i].end());
	total_count = -1;
	traverse(0, 0);
	IO::Write(total_answer);
}
